import{_ as t,o,c as d,a2 as a}from"./chunks/framework.il0noOp3.js";const g=JSON.parse(`{"title":"Category Structure","description":"Maps AzureScout -Category parameter values to Microsoft's Azure portal categories and module folder paths.","frontmatter":{"description":"Maps AzureScout -Category parameter values to Microsoft's Azure portal categories and module folder paths."},"headers":[],"relativePath":"category-structure.md","filePath":"category-structure.md"}`),r={name:"category-structure.md"};function c(s,e,n,i,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="category-structure" tabindex="-1">Category Structure <a class="header-anchor" href="#category-structure" aria-label="Permalink to &quot;Category Structure&quot;">​</a></h1><p>This page maps the <code>-Category</code> parameter values to Microsoft&#39;s official Azure portal category names, the corresponding folder paths in the module tree, and the primary resource types covered.</p><h2 id="category-mapping" tabindex="-1">Category Mapping <a class="header-anchor" href="#category-mapping" aria-label="Permalink to &quot;Category Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>-Category</code> Value</th><th>Azure Portal Label</th><th>Module Folder Path</th></tr></thead><tbody><tr><td><code>AI</code></td><td>AI + Machine Learning</td><td><code>manifests/collectors/AI/</code></td></tr><tr><td><code>Analytics</code></td><td>Analytics</td><td><code>manifests/collectors/Analytics/</code></td></tr><tr><td><code>Compute</code></td><td>Compute</td><td><code>manifests/collectors/Compute/</code></td></tr><tr><td><code>Containers</code></td><td>Containers</td><td><code>manifests/collectors/Containers/</code></td></tr><tr><td><code>Databases</code></td><td>Databases</td><td><code>manifests/collectors/Databases/</code></td></tr><tr><td><code>DevOps</code></td><td>DevOps</td><td><code>manifests/collectors/DevOps/</code></td></tr><tr><td><code>General</code></td><td>General</td><td><code>manifests/collectors/General/</code></td></tr><tr><td><code>Hybrid</code></td><td>Hybrid + multicloud</td><td><code>manifests/collectors/Hybrid/</code></td></tr><tr><td><code>Identity</code></td><td>Identity</td><td><code>manifests/collectors/Identity/</code></td></tr><tr><td><code>Integration</code></td><td>Integration</td><td><code>manifests/collectors/Integration/</code></td></tr><tr><td><code>IoT</code></td><td>Internet of Things</td><td><code>manifests/collectors/IoT/</code></td></tr><tr><td><code>Management</code></td><td>Management and governance</td><td><code>manifests/collectors/Management/</code></td></tr><tr><td><code>Migration</code></td><td>Migration</td><td><code>manifests/collectors/Migration/</code></td></tr><tr><td><code>Monitor</code></td><td>Monitor</td><td><code>manifests/collectors/Monitor/</code></td></tr><tr><td><code>Networking</code></td><td>Networking</td><td><code>manifests/collectors/Networking/</code></td></tr><tr><td><code>Security</code></td><td>Security</td><td><code>manifests/collectors/Security/</code></td></tr><tr><td><code>Storage</code></td><td>Storage</td><td><code>manifests/collectors/Storage/</code></td></tr><tr><td><code>Web</code></td><td>Web &amp; Mobile</td><td><code>manifests/collectors/Web/</code></td></tr></tbody></table><p><code>DevOps</code>, <code>General</code> and <code>Migration</code> are canonical categories as of v3.1.0 (AB#6741), each with its own manifest folder, <code>[ValidateSet]</code> entry and report heading. They are <strong>not</strong> aliases for anything — see the warning below.</p><h2 id="accepted-aliases" tabindex="-1">Accepted Aliases <a class="header-anchor" href="#accepted-aliases" aria-label="Permalink to &quot;Accepted Aliases&quot;">​</a></h2><p>The following long-form names (as shown in the Azure portal) are automatically normalized to their short equivalents. Matching is case-insensitive.</p><table tabindex="0"><thead><tr><th>Input</th><th>Normalized to</th></tr></thead><tbody><tr><td><code>AI + machine learning</code></td><td><code>AI</code></td></tr><tr><td><code>AI+machine learning</code></td><td><code>AI</code></td></tr><tr><td><code>Machine Learning</code></td><td><code>AI</code></td></tr><tr><td><code>Internet of Things</code></td><td><code>IoT</code></td></tr><tr><td><code>Monitoring</code></td><td><code>Monitor</code></td></tr><tr><td><code>Management and governance</code></td><td><code>Management</code></td></tr><tr><td><code>Management &amp; governance</code></td><td><code>Management</code></td></tr><tr><td><code>Web &amp; Mobile</code></td><td><code>Web</code></td></tr><tr><td><code>Web and mobile</code></td><td><code>Web</code></td></tr><tr><td><code>Mobile</code></td><td><code>Web</code></td></tr><tr><td><code>Hybrid + multicloud</code></td><td><code>Hybrid</code></td></tr><tr><td><code>Hybrid+multicloud</code></td><td><code>Hybrid</code></td></tr><tr><td><code>Networking + CDN</code></td><td><code>Networking</code></td></tr><tr><td><code>Networking+CDN</code></td><td><code>Networking</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>DevOps</code> and <code>Migration</code> are not aliases</p><p>Both used to be listed here resolving to <code>Management</code>. They are <strong>canonical categories</strong> as of v3.1.0, each with its own manifest directory, so folding either into <code>Management</code> would silently run the wrong collectors. The old alias entries were also unreachable even before the removal — neither string was in the <code>-Category</code> <code>[ValidateSet]</code>, so parameter binding rejected them before the alias map was ever consulted.</p></div><p>See the <a href="./category-reference.html">Category Reference</a> for the full mapping of report section headings to categories, collector folders, and module counts.</p><h2 id="category-selection-logic" tabindex="-1">Category Selection Logic <a class="header-anchor" href="#category-selection-logic" aria-label="Permalink to &quot;Category Selection Logic&quot;">​</a></h2><p>When <code>-Category</code> is specified, AzureScout:</p><ol><li>Normalizes any alias values to canonical short names</li><li>Loads only the module files inside the matching category folders</li><li>Restricts Resource Graph and REST API queries to those modules&#39; resource types</li><li>Generates reports containing only the selected categories</li></ol><p>When <code>-Category All</code> is used (the default), all category folders are included.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run only Compute and Security modules</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Category Compute</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Security</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Full portal name also works</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Category </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;AI + machine learning&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default — all categories</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="adding-a-new-category" tabindex="-1">Adding a New Category <a class="header-anchor" href="#adding-a-new-category" aria-label="Permalink to &quot;Adding a New Category&quot;">​</a></h2><p>To add a new category:</p><ol><li>Create a new folder under <code>manifests/collectors/</code></li><li>Add the folder name to <code>[ValidateSet]</code> for <code>-Category</code> in <code>Invoke-AzureScout.ps1</code></li><li>Add any alias entries to the <code>$_categoryAliasMap</code> hashtable in <code>Invoke-AzureScout.ps1</code></li><li>Update the <a href="./coverage-table.html">Coverage Table</a> with the new modules</li></ol><p>See <a href="./contributing.html">Contributing</a> for full guidance on adding modules.</p>`,19)])])}const u=t(r,[["render",c]]);export{g as __pageData,u as default};
